gameActivityImportAdditions.insert:
import android.os.Build;
import android.os.VibrationEffect;
import android.os.Vibrator;
import android.os.VibratorManager;
import java.lang.reflect.Method;

gameActivityClassAdditions.insert:
public long[] AndroidThunkJava_OpenMobileHapticsQueryCapabilities()
{
    try
    {
        Vibrator vibrator;
        if (Build.VERSION.SDK_INT >= 31)
        {
            VibratorManager manager =
                (VibratorManager)getSystemService(VIBRATOR_MANAGER_SERVICE);
            if (manager == null)
            {
                return new long[] {-1L};
            }
            vibrator = manager.getDefaultVibrator();
        }
        else
        {
            vibrator = (Vibrator)getSystemService(VIBRATOR_SERVICE);
        }
        if (vibrator == null)
        {
            return new long[] {-1L};
        }
        if (!vibrator.hasVibrator())
        {
            return new long[] {0L, 0L, 0L, -1L, -1L, -1L};
        }

        long flags = 1L | 2L;
        if (Build.VERSION.SDK_INT >= 26)
        {
            flags |= 32L | 64L;
            if (vibrator.hasAmplitudeControl())
            {
                flags |= 8L;
            }
        }
        long presetSupport = 0L;
        long primitiveSupport = 0L;
        long maxControlPoints = -1L;
        long maxDurationMillis = -1L;
        long minTimingMillis = -1L;
        if (Build.VERSION.SDK_INT >= 30)
        {
            int[] effects = vibrator.areEffectsSupported(
                VibrationEffect.EFFECT_TICK,
                VibrationEffect.EFFECT_CLICK,
                VibrationEffect.EFFECT_HEAVY_CLICK,
                VibrationEffect.EFFECT_DOUBLE_CLICK
            );
            for (int index = 0; index < effects.length; ++index)
            {
                presetSupport |= ((long)effects[index] & 3L) << (index * 2);
            }
            flags |= 1024L;
            boolean[] primitives = vibrator.arePrimitivesSupported(
                VibrationEffect.Composition.PRIMITIVE_CLICK,
                VibrationEffect.Composition.PRIMITIVE_THUD,
                VibrationEffect.Composition.PRIMITIVE_SPIN,
                VibrationEffect.Composition.PRIMITIVE_QUICK_RISE,
                VibrationEffect.Composition.PRIMITIVE_SLOW_RISE,
                VibrationEffect.Composition.PRIMITIVE_QUICK_FALL,
                VibrationEffect.Composition.PRIMITIVE_TICK,
                VibrationEffect.Composition.PRIMITIVE_LOW_TICK
            );
            for (int index = 0; index < primitives.length; ++index)
            {
                if (primitives[index])
                {
                    primitiveSupport |= 1L << index;
                }
            }
            flags |= 2048L;
            if (primitiveSupport != 0L)
            {
                flags |= 4L | 128L;
            }
        }
        if (Build.VERSION.SDK_INT >= 36)
        {
            try
            {
                Method envelopeSupportMethod = Vibrator.class.getMethod(
                    "areEnvelopeEffectsSupported"
                );
                boolean envelopeSupported =
                    (Boolean)envelopeSupportMethod.invoke(vibrator);
                flags |= 4096L | 8192L;
                if (envelopeSupported)
                {
                    flags |= 256L;
                    Object envelopeInfo = Vibrator.class.getMethod(
                        "getEnvelopeEffectInfo"
                    ).invoke(vibrator);
                    if (envelopeInfo != null)
                    {
                        maxControlPoints = ((Number)envelopeInfo.getClass()
                            .getMethod("getMaxSize").invoke(envelopeInfo)).longValue();
                        maxDurationMillis = ((Number)envelopeInfo.getClass()
                            .getMethod("getMaxDurationMillis").invoke(envelopeInfo)).longValue();
                        minTimingMillis = ((Number)envelopeInfo.getClass()
                            .getMethod("getMinControlPointDurationMillis")
                            .invoke(envelopeInfo)).longValue();
                    }
                    Object frequencyProfile = Vibrator.class.getMethod(
                        "getFrequencyProfile"
                    ).invoke(vibrator);
                    if (frequencyProfile != null)
                    {
                        flags |= 512L;
                    }
                }
            }
            catch (ReflectiveOperationException exception)
            {
            }
        }
        return new long[] {
            flags,
            presetSupport,
            primitiveSupport,
            maxControlPoints,
            maxDurationMillis,
            minTimingMillis
        };
    }
    catch (Exception exception)
    {
        return new long[] {-1L};
    }
}
